#[no_mangle]
pub extern "C" fn aro_plugin_info() -> *mut c_char { … }
#[no_mangle]
pub extern "C" fn aro_plugin_execute(action: *const c_char, input: *const c_char) -> *mut c_char { … }
#[no_mangle]
pub extern "C" fn aro_plugin_qualifier(name: *const c_char, input: *const c_char) -> *mut c_char { … }
#[no_mangle]
pub extern "C" fn aro_plugin_free(ptr: *mut c_char) { … }

Four exports: metadata, action dispatch, qualifier dispatch, and the free the host calls when it is done with a returned string.

from aro_plugin_sdk import plugin, action, qualifier, export_abi

@plugin(name="plugin-tides", version="1.0.0", handle="Tides")
class Tides:
    @action
    def predict(self, args):
        return {"high": args["port"]}

    @qualifier
    def normalise(self, value):
        return value.strip().lower()

export_abi(globals())

The decorators register the action and the qualifier; `export_abi(globals())` is what creates the C entry points the host dispatches through.

#include "aro_plugin_sdk.h"

ARO_ACTION(predict) {
    return aro_json_object("high", "06:12");
}

ARO_QUALIFIER(normalise) {
    return aro_string(aro_trim(input));
}

ARO_PLUGIN("plugin-tides", "1.0.0")

The macros generate the four C ABI exports, so the plugin does not write aro_plugin_info or the dispatchers by hand.

@AROExport
let plugin = AROPlugin(
    name: "plugin-tides",
    version: "1.0.0",
    handle: "Tides",
    actions: ["predict": { args in ["high": "06:12"] }]
)

The @AROExport macro generates every C ABI export — the metadata, the action and qualifier dispatchers, and the free — so the plugin writes none of them.
